sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {

    if (isLoading) {
        setPaymentFields(newValue);
        return;
    }

    setPaymentFields(newValue);

    function setPaymentFields(mode) {

        // Online payment
        if (mode == 'online') {

			g_form.setMandatory('collected_by', false);
            g_form.setDisplay('collected_by', false);
			g_form.clearValue('collected_by');

            g_form.setDisplay('stripe_reference', true);
            g_form.setMandatory('stripe_reference', true);




        } else if (mode == 'cash') { // Cash payment

            g_form.setDisplay('stripe_reference', false);
            g_form.setMandatory('stripe_reference', false);
			g_form.clearValue('stripe_reference');

            g_form.setDisplay('collected_by', true);
            g_form.setMandatory('collected_by', true);

        } else { // No mode selected

             g_form.setMandatory('stripe_reference', false);
			g_form.setDisplay('stripe_reference', false);	
			g_form.clearValue('stripe_reference');

            g_form.setMandatory('collected_by', false);
			g_form.setDisplay('collected_by', false);
			g_form.clearValue('collected_by');


        }
    }
}
